args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?label ?birth ?death ( (YEAR(?death) - YEAR(?birth)) AS ?lifespanYears )
WHERE {
  VALUES ?person { dbr:Martino_Finotto dbr:Franklin_Edson }
  OPTIONAL { ?person dbo:birthDate ?birth . }
  OPTIONAL { ?person dbo:deathDate ?death . }
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
  FILTER(BOUND(?birth) && BOUND(?death))
}
ORDER BY DESC(?lifespanYears)

